#include <fcntl.h>
#include <unistd.h>
#include <stdio.h>

int main() {
    char buffer[100];
    int fd = open("example.txt", O_RDONLY);
    if (fd == -1) {
        perror("open failed");
        return 1;
    }
    int bytes = read(fd, buffer, sizeof(buffer) - 1);
    if (bytes == -1) {
        perror("read failed");
        return 1;
    }
    buffer[bytes] = '\0';
    printf("Read %d bytes: %s\n", bytes, buffer);
    close(fd);
    return 0;
}

#include <sys/types.h>
#include <sys/wait.h>
#include <unistd.h>
#include <stdio.h>

int main() {
    pid_t pid = fork();
    if (pid == 0) {
        printf("Child: Doing work...\n");
        return 42;
    } else {
        int status;
        wait(&status);
        if (WIFEXITED(status)) {
            printf("Parent: Child exited with code %d\n", WEXITSTATUS(status));
        }
    }
    return 0;
}
